begin;
select plan(29);
insert into auth.users(id,aud,role,email,email_confirmed_at) values
('29000000-0000-4000-8000-000000000001','authenticated','authenticated','correction@example.test',now()),
('29000000-0000-4000-8000-000000000002','authenticated','authenticated','stranger@example.test',now()),
('29000000-0000-4000-8000-000000000003','authenticated','authenticated','staff@example.test',now());
insert into public.staff_roles(user_id,role) values('29000000-0000-4000-8000-000000000003','admin');
update public.onboarding_settings set enabled=true;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"29000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.submit_basic_onboarding('Test Minor','+919999999999','https://linkedin.com/in/test',((now() at time zone 'Asia/Kolkata')::date-interval '17 years')::date);
select public.reserve_onboarding_document('photo');
select public.reserve_onboarding_document('government_id','pan');
select throws_ok($$select public.request_onboarding_corrections(auth.uid(),'Replace blurry ID photograph')$$,'42501','Independent admin review required','owner cannot reopen application');
reset role;
insert into storage.objects(bucket_id,name) select 'onboarding-documents',object_path from public.onboarding_documents where user_id='29000000-0000-4000-8000-000000000001';
select public.finalize_onboarding_document(id) from public.onboarding_documents where user_id='29000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"29000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.request_onboarding_corrections('29000000-0000-4000-8000-000000000001','short')$$,'22023','Correction reason must contain 10 to 1000 characters','meaningful correction reason required');
select lives_ok($$select public.request_onboarding_corrections('29000000-0000-4000-8000-000000000001','Replace blurry ID photograph')$$,'staff requests correction');
select is((select count(*)::integer from public.onboarding_documents where user_id='29000000-0000-4000-8000-000000000001' and expires_at<=now()),2,'all old copies expired immediately');
select throws_ok($$select public.review_basic_onboarding('29000000-0000-4000-8000-000000000001','approved')$$,'22023','Pending application required','cannot approve during corrections');
select is((select reason from public.onboarding_reviews where user_id='29000000-0000-4000-8000-000000000001'),'Replace blurry ID photograph','reason retained in immutable review');
select throws_ok($$update public.onboarding_reviews set reason='Changed note'$$,'42501',null,'staff cannot rewrite correction history');
select set_config('request.jwt.claims','{"sub":"29000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.resubmit_basic_onboarding('Other Person','+919999999999','https://linkedin.com/in/test','1990-01-01')$$,'22023','Corrections requested application required','other member cannot resubmit owner application');
select set_config('request.jwt.claims','{"sub":"29000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.resubmit_basic_onboarding('Test Minor','+919999999999','https://linkedin.com/in/test',((now() at time zone 'Asia/Kolkata')::date-interval '15 years')::date)$$,'22023','Minimum age is 16','corrections revalidate age');
select lives_ok($$select public.resubmit_basic_onboarding('Corrected Minor','+919999999999','https://linkedin.com/in/test',((now() at time zone 'Asia/Kolkata')::date-interval '17 years')::date)$$,'owner resubmits');
select is((select revision from public.basic_onboarding_applications where user_id=auth.uid()),2,'resubmission advances revision');
select is((select count(*)::integer from public.onboarding_resubmissions where user_id=auth.uid()),1,'owner resubmission separately audited');
select is((select count(*)::integer from public.onboarding_reviews where user_id=auth.uid()),1,'resubmission does not impersonate staff');
select lives_ok($$select public.reserve_onboarding_document('photo')$$,'new photo reservation allowed while old object remains');
select lives_ok($$select public.reserve_onboarding_document('government_id','passport')$$,'new ID reservation allowed');
select set_config('request.jwt.claims','{"sub":"29000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.review_basic_onboarding('29000000-0000-4000-8000-000000000001','approved')$$,'40001','Application changed; reload before reviewing','stale review cannot approve resubmission');
select throws_ok($$select public.request_onboarding_corrections('29000000-0000-4000-8000-000000000001','Replace blurry ID photograph')$$,'40001','Application changed; reload before reviewing','stale correction cannot reopen resubmission');
select throws_ok($$select public.review_basic_onboarding('29000000-0000-4000-8000-000000000001','approved',p_expected_revision=>2)$$,'22023','Unexpired photo and government ID uploads required','old stored copies cannot pass new review');
reset role;
insert into storage.objects(bucket_id,name) select 'onboarding-documents',object_path from public.onboarding_documents where user_id='29000000-0000-4000-8000-000000000001' and expires_at>now();
select public.finalize_onboarding_document(id) from public.onboarding_documents where user_id='29000000-0000-4000-8000-000000000001' and expires_at>now();
set local role authenticated;
select throws_ok($$select public.review_basic_onboarding('29000000-0000-4000-8000-000000000001','approved',p_expected_revision=>2)$$,'22023','Reviewed guardian email evidence required','guardian evidence explicitly required anew');
select lives_ok($$select public.review_basic_onboarding('29000000-0000-4000-8000-000000000001','approved','guardian@example.test','synthetic-message-reference',now()-interval '1 hour',2)$$,'fresh review approves corrected application');
select throws_ok($$select public.request_onboarding_corrections('29000000-0000-4000-8000-000000000001','Replace blurry ID photograph',2)$$,'22023','Pending or rejected application required','approved verification cannot be reopened');
select set_config('request.jwt.claims','{"sub":"29000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select public.submit_basic_onboarding('Rejected Person','+919999999999','https://linkedin.com/in/rejected','1990-01-01');
select set_config('request.jwt.claims','{"sub":"29000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select public.review_basic_onboarding('29000000-0000-4000-8000-000000000002','rejected');
select lives_ok($$select public.request_onboarding_corrections('29000000-0000-4000-8000-000000000002','Provide a readable identity photograph')$$,'staff can return rejected application for corrections');
select set_config('request.jwt.claims','{"sub":"29000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.resubmit_basic_onboarding('Rejected Person','--------','https://linkedin.com/in/test','1990-01-01')$$,'22023','Name, phone and personal LinkedIn profile are required','resubmission requires valid phone');
select throws_ok($$select public.resubmit_basic_onboarding('Rejected Person','+919999999999','https://linkedin.com/company/test','1990-01-01')$$,'22023','Name, phone and personal LinkedIn profile are required','resubmission requires personal LinkedIn');
select is((select count(*)::integer from public.onboarding_resubmissions),0,'other applicant cannot read owner resubmission history');
reset role;
update auth.users set email_confirmed_at=null where id='29000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.resubmit_basic_onboarding('Rejected Person','+919999999999','https://linkedin.com/in/test','1990-01-01')$$,'42501','Verified email required','resubmission rechecks verified email');
reset role;
select is((select count(*)::integer from public.memberships where user_id='29000000-0000-4000-8000-000000000001' and status='active'),0,'corrected verification grants no paid entitlement');
update public.onboarding_settings set enabled=false;
set local role authenticated;
select throws_ok($$select public.request_onboarding_corrections('29000000-0000-4000-8000-000000000001','Replace blurry ID photograph',2)$$,'42501','Onboarding is disabled','correction gate remains enforced');
select throws_ok($$select public.resubmit_basic_onboarding('Test Person','+919999999999','https://linkedin.com/in/test','1990-01-01')$$,'42501','Onboarding is disabled','resubmission gate remains enforced');
select * from finish();
rollback;
